// ═══════════════════════════════════════════════════════════════
//  Packmates AI — i18n foundation.
//
//  Single source of truth for UI strings, ready for more languages
//  without any further refactoring: adding a language is just adding
//  a key to TRANSLATIONS (and LANGUAGE_NAMES so it shows up in the
//  switcher) - no template/DOM changes needed anywhere.
//
//  Item/category names from lib/packing-items.js are a SEPARATE
//  translation surface, covered by ITEM_TRANSLATIONS/CATEGORY_KEYS
//  further down (they're also used as storage/matching keys, so their
//  canonical English `name` fields must never change - only what's
//  displayed does).
//
//  language preference lives in pm_profile.language (see profile.html's
//  _pmProfile()/_savePmProfile() for the existing merge-write convention
//  this follows), and syncs across a person's devices via auth.js's
//  DB.saveProfile()/syncProfile() + the profiles.language column
//  (supabase/migrations/20260927000001_add_profile_language.sql) -
//  setLang() below already calls DB.saveProfile(), and profile.html
//  already calls DB.syncProfile() on load, so no further wiring is
//  needed here.
// ═══════════════════════════════════════════════════════════════

