      'Arquitecta de día, exploradora de fin de semana. Persigo atardeceres, comida callejera y museos escondidos. Siempre planeando la próxima escapada ✈️',
    'Travel photographer & food blogger. If there\'s a train to take it, I\'m on it. Documenting stories one frame at a time 📸':
      'Fotógrafo de viajes y bloguero de comida. Si hay un tren que tomar, ahí estoy. Documentando historias una toma a la vez 📸',
    'Software engineer who travels to recharge. Obsessed with minimalist packing and finding the calmest spots in busy cities 🎒':
      'Ingeniera de software que viaja para recargar energías. Obsesionada con el empaque minimalista y encontrar los rincones más tranquilos en ciudades ajetreadas 🎒',
    'Retired footballer turned full-time traveler. Love adventure sports, off-the-beaten-path villages, and long dinners with locals 🌍':
      'Exfutbolista convertido en viajero de tiempo completo. Amo los deportes de aventura, los pueblos poco explorados y las cenas largas con locales 🌍',
