      'Diseñadora de moda apasionada por el viaje lento. Paso semanas, no días, en cada ciudad. Galerías de arte, jardines botánicos y tiendas vintage 🌿',
    'Marine biologist & ocean lover. Every trip involves water — diving, surfing, or just watching waves. The reef is home 🌊':
      'Biólogo marino y amante del océano. Cada viaje involucra agua: buceo, surf o simplemente mirar las olas. El arrecife es mi hogar 🌊',
    'UX designer & solo traveler. I find joy in planning detailed itineraries and ditching half of them. Chai > coffee ☕':
      'Diseñadora UX y viajera solitaria. Disfruto planear itinerarios detallados y luego abandonar la mitad. El chai le gana al café ☕',
    'Environmental consultant who offsets every flight. Obsessed with national parks, mountain lodges, and zero-waste travel 🏔️':
      'Consultor ambiental que compensa cada vuelo. Obsesionado con los parques nacionales, las cabañas de montaña y el turismo cero residuos 🏔️',
