    'Architect by day, explorer by weekend. I chase sunsets, street food, and hidden museums. Always planning the next escape ✈️': 'Архітекторка вдень, мандрівниця у вихідні. Ганяюся за заходами сонця, вуличною їжею та прихованими музеями. Завжди планую наступну втечу ✈️',
    'Travel photographer & food blogger. If there\'s a train to take it, I\'m on it. Documenting stories one frame at a time 📸': 'Тревел-фотограф і фуд-блогер. Якщо є потяг, на який можна сісти — я вже в ньому. Документую історії кадр за кадром 📸',
    'Software engineer who travels to recharge. Obsessed with minimalist packing and finding the calmest spots in busy cities 🎒': 'Інженерка-програмістка, яка подорожує, щоб перезарядитися. Одержима мінімалістичним пакуванням і пошуком найспокійніших куточків у метушливих містах 🎒',
    'Retired footballer turned full-time traveler. Love adventure sports, off-the-beaten-path villages, and long dinners with locals 🌍': 'Колишній футболіст, який став мандрівником на повний день. Люблю екстремальні види спорту, села осторонь туристичних маршрутів і довгі вечері з місцевими 🌍',
    'Fashion designer with a passion for slow travel. I spend weeks not days in each city. Art galleries, botanical gardens & vintage shops 🌿': 'Дизайнерка одягу, закохана у повільні подорожі. Я проводжу тижні, а не дні, в кожному місті. Художні галереї, ботанічні сади й вінтажні крамниці 🌿',
    'Marine biologist & ocean lover. Every trip involves water — diving, surfing, or just watching waves. The reef is home 🌊': 'Морський біолог і любитель океану. Кожна подорож пов\'язана з водою — дайвінг, серфінг або просто споглядання хвиль. Риф — це дім 🌊',
    'UX designer & solo traveler. I find joy in planning detailed itineraries and ditching half of them. Chai > coffee ☕': 'UX-дизайнерка та самотня мандрівниця. Отримую задоволення від планування детальних маршрутів і скасування половини з них. Чай кращий за каву ☕',
    'Environmental consultant who offsets every flight. Obsessed with national parks, mountain lodges, and zero-waste travel 🏔️': 'Консультант з екології, який компенсує викиди від кожного польоту. Одержимий національними парками, гірськими притулками та безвідходними подорожами 🏔️',
