function getLang() {
  try {
    const saved = JSON.parse(localStorage.getItem('pm_profile') || '{}').language;
    if (saved && TRANSLATIONS[saved]) return saved;
  } catch (e) {}
  const device = (navigator.language || 'en').slice(0, 2).toLowerCase();
  return TRANSLATIONS[device] ? device : 'en';
}

/* BCP-47 locale for toLocaleDateString()/toLocaleString() calls - affects
   month/weekday names and date ordering, not the app's own UI strings
   (that's tr()). Call wherever a date gets formatted for display. */
function dateLocale() {
  return { en: 'en-US', es: 'es-ES', uk: 'uk-UA', pt: 'pt-BR' }[getLang()] || 'en-US';
}

/* Temperature display unit ('F' or 'C') - independent of app language
   (a Ukrainian user may still prefer °F, an American user °C), so it's
   its own pm_profile field rather than derived from getLang(). Every
   weather fetch in the app always requests &temperature_unit=fahrenheit
   from Open-Meteo and caches/stores that raw °F number - formatTemp()
   converts for display only, so there's one unit of truth everywhere
   else (push-copy thresholds, weather-change detection, etc). Defaults
   to 'F' to match the app's existing behavior for anyone who hasn't
   picked a preference. */
function getTempUnit() {
  try {
    const saved = JSON.parse(localStorage.getItem('pm_profile') || '{}').tempUnit;
    if (saved === 'C' || saved === 'F') return saved;
  } catch (e) {}
  return 'F';
}

function setTempUnit(unit) {
  if (unit !== 'C' && unit !== 'F') return;
  let merged;
  try { merged = { ...JSON.parse(localStorage.getItem('pm_profile') || '{}'), tempUnit: unit }; }
  catch (e) { merged = { tempUnit: unit }; }
  localStorage.setItem('pm_profile', JSON.stringify(merged));
  if (typeof DB !== 'undefined' && DB.saveProfile) DB.saveProfile(merged);
}

/* fahrenheit: a number already in °F (every weather fetch's native
   unit). Rounds at display time, after the unit conversion - the stored
   value is itself already rounded to a whole °F, so this is "round a
   whole °F converted to °C", not a double-rounded loss of precision
   beyond what caching already accepts. */
function formatTemp(fahrenheit) {
  if (fahrenheit === null || fahrenheit === undefined || isNaN(fahrenheit)) return '—';
  const unit = getTempUnit();
  const value = unit === 'C' ? Math.round((fahrenheit - 32) * 5 / 9) : Math.round(fahrenheit);
  return `${value}°${unit}`;
}

/* Named tr(), not t() - this codebase uses `t` everywhere as the loop
   variable for "trip" (.map(t => ...), etc.), which would silently
   shadow a global t() the moment a translation call happened inside
   one of those callbacks (exactly what broke the dashboard: t is not
   a function, thrown mid-render, halting everything after it).
   vars: optional {name: 'Alex'} map - substitutes {name} placeholders
   in the translated string. Word order around the placeholder is part
   of each language's own translation, not fixed by the caller, so this
   stays safe to use once more languages exist. */
function tr(key, vars) {
  const lang = getLang();
  const dict = TRANSLATIONS[lang] || TRANSLATIONS.en;
  let str = dict[key] ?? TRANSLATIONS.en[key] ?? key;
  if (vars) {
    Object.keys(vars).forEach(k => { str = str.split('{' + k + '}').join(vars[k]); });
  }
  return str;
}

/* One badge-style image per language, shown briefly by
   showLangSwitchSplash() below when the person switches languages.
   A language with no entry here just skips the splash and reloads
   immediately - never a hard requirement to add one. */
const LANG_SPLASH_IMAGES = { en: 'img/lang-en.png', es: 'img/lang-es.png', uk: 'img/lang-uk.png', pt: 'img/lang-pt.png' };

function showLangSwitchSplash(lang) {
  return new Promise((resolve) => {
    const src = LANG_SPLASH_IMAGES[lang];
    if (!src || typeof document === 'undefined' || !document.body) { resolve(); return; }
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:999999;background:#fff;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity 0.4s ease;';
    const img = document.createElement('img');
    img.alt = '';
    img.style.cssText = 'width:min(70vw,340px);height:min(70vw,340px);object-fit:contain;transform:scale(0.85);opacity:0;transition:transform 0.5s cubic-bezier(0.22,1,0.36,1),opacity 0.5s ease;';
    overlay.appendChild(img);
    document.body.appendChild(overlay);
    let started = false;
    const start = () => {
      if (started) return;
      started = true;
      requestAnimationFrame(() => {
        overlay.style.opacity = '1';
        img.style.transform = 'scale(1)';
        img.style.opacity = '1';
      });
      setTimeout(() => {
        overlay.style.opacity = '0';
        img.style.transform = 'scale(1.05)';
        setTimeout(() => { overlay.remove(); resolve(); }, 400);
      }, 1500);
    };
    img.onload = start;
    img.onerror = () => { overlay.remove(); resolve(); };
    img.src = src;
    setTimeout(start, 200); // don't block on a slow/cached-but-unfired load
  });
}

function setLang(lang) {
  if (!TRANSLATIONS[lang]) return;
  let merged;
  try { merged = { ...JSON.parse(localStorage.getItem('pm_profile') || '{}'), language: lang }; }
  catch (e) { merged = { language: lang }; }
  localStorage.setItem('pm_profile', JSON.stringify(merged));
  /* Same DB.saveProfile() call every other profile field uses (auth.js) -
     syncs this language choice to Supabase's profiles.language column so
     it carries over to the person's other signed-in devices. */
  if (typeof DB !== 'undefined' && DB.saveProfile) DB.saveProfile(merged);
  /* window.top, not location: the persistent bottom-nav chrome (and its
     own data-i18n text) lives only in the app-shell's host document
     (lib/app-shell.js) - this page can be running inside one of that
     shell's background tab iframes, where a plain location.reload() would
     refresh only this iframe's content and leave the host's nav bar
     stuck showing whichever language was active at the shell's last cold
     load. Reloading window.top instead re-renders the whole shell,
     nav included. */
  showLangSwitchSplash(lang).then(() => {
    const top = window.top || window;
    /* Native only: window.top's own location is whatever page the shell
       happened to load/re-host as (app-shell.js's hostPage) - not
       reliably index.html, and a plain reload() lands back on wherever
       that was instead of Home, which is what this is actually for. On
       plain web there's no shell/iframe tabs to land on - reloading in
       place (staying on Settings) is the expected, unsurprising result
       of a language switch there, so this only redirects on native. */
    const isNative = (top.Capacitor && top.Capacitor.isNativePlatform && top.Capacitor.isNativePlatform())
      || (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
    if (isNative) top.location.replace('index.html');
    else top.location.reload();
  });
}

/* Walks [data-i18n] (textContent) and [data-i18n-attr] (one or more
   "attr:key" pairs, semicolon-separated, e.g. data-i18n-attr="placeholder:profile.hero.namePlaceholder")
   and fills in the current language's strings. Call after any DOM
   this needs to cover is in place (static markup: on load; JS-rendered
   sections: right after they're inserted). */
function applyTranslations(root) {
  const scope = root || document;
  scope.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = tr(el.getAttribute('data-i18n'));
  });
  scope.querySelectorAll('[data-i18n-attr]').forEach(el => {
    el.getAttribute('data-i18n-attr').split(';').forEach(pair => {
      const idx = pair.indexOf(':');
      if (idx === -1) return;
      const attr = pair.slice(0, idx).trim();
      const key = pair.slice(idx + 1).trim();
      if (attr && key) el.setAttribute(attr, tr(key));
    });
  });
  document.documentElement.lang = getLang();
}
